import os
from docx.shared import Inches, Pt, RGBColor
from docx.enum.text import WD_ALIGN_PARAGRAPH
from doc_builder import (
    add_para, add_h1, add_h2, add_h3,
    add_bullet, add_styled_table, add_screenshot_placeholder, set_font
)

def add_chapter_one(doc):
    add_h1(doc, "CHAPTER ONE INTRODUCTION")
    
    add_h2(doc, "1.1 Background")
    add_para(doc, "Agriculture represents the undeniable cornerstone and bedrock of the Ethiopian economy, societal stability, and cultural heritage. According to comprehensive empirical assessments and surveys conducted by the Ethiopian Ministry of Agriculture (MoA), the Central Statistical Agency (CSA), and the Food and Agriculture Organization (FAO), smallholder subsistence farming accounts for upwards of 85% of total national employment, generates approximately 32% of the national Gross Domestic Product (GDP), and provides more than 70% of foreign currency export earnings. Across the country's diverse agro-ecological landscape—ranging from the cool temperate highlands (Dega) and intermediate valleys (Woina Dega) to the hot semi-arid lowlands (Kolla)—millions of smallholder agrarian households cultivate primary cereal staples such as Teff (Eragrostis tef), Maize (Zea mays), Wheat (Triticum aestivum), Barley, and Sorghum, alongside vital commercial horticulture including Tomato, Potato, Pepper, and Coffee.")
    add_para(doc, "Despite this paramount economic and social role, agricultural productivity per unit area of cultivated land across Ethiopia remains markedly depressed below continental and global agronomic benchmarks. While systemic factors such as soil acidity, land fragmentation, and erratic rainfall patterns contribute to this gap, the most volatile, recurring, and devastating threat to crop yields is the rampant proliferation of infectious phytopathogenic foliar diseases and insect pests. Under shifting microclimatic conditions, fungal blights, bacterial wilts, and viral infections spread across farming communities with aggressive reproductive fecundity.")
    add_para(doc, "For example, in maize-producing corridors, Northern Corn Leaf Blight (Exserohilum turcicum) and Common Rust (Puccinia sorghi) routinely decimate photosynthetic leaf area, reducing grain harvest weights by 30% to 70%. In wheat-growing zones such as Arsi, Bale, and North Shewa, epidemics of Stem Rust (Puccinia graminis) and Stripe Rust have historically caused 100% complete field destruction within single cropping seasons. Similarly, high-value smallholder horticultural crops, particularly Tomato and Potato, are perpetually jeopardized by Late Blight (Phytophthora infestans) and Early Blight (Alternaria solani), which destroy crops within days of foliar symptom manifestation.")
    add_para(doc, "The challenge is severely magnified by smallholder diagnostic ambiguity. Rural farmers lack formalized phytopathological training. Symptoms of fungal leaf blight, bacterial spot, viral chlorosis, and physiological stress (such as nitrogen, zinc, or phosphorus deficiency) exhibit remarkably similar visual markers to the untrained human eye. Consequently, when a farmer notices necrotic brown spots or yellowing leaves, they frequently misdiagnose the underlying causative agent. This misdiagnosis prompts farmers to purchase incorrect, unnecessary, or unverified agrochemicals from open local markets. Such misguided applications not only waste scarce household financial savings but also induce environmental toxicity, accelerate chemical resistance among pest populations, and fail completely to halt the spread of the pathogen.")
    add_para(doc, "Historically, the institutional mechanism designed to address these frontline agrarian challenges is the Ethiopian public agricultural extension system. Structurally organized from the Federal Ministry down through Regional Agricultural Bureaus, Zonal Departments, Woreda (District) Agricultural Offices, and rural Kebele (Sub-district) Farmer Training Centers (FTCs), extension agents known as Development Agents (DAs) are stationed to provide technical guidance. Each Kebele is typically assigned three specialized extension workers: one for Crop Production, one for Animal Husbandry, and one for Natural Resource Management.")
    add_para(doc, "However, as detailed in Section 1.2, this conventional, in-person advisory modality faces severe operational crises. Prohibitive agent-to-farmer ratios, extreme topographical barriers, unpaved rural road networks, seasonal river crossings, and paper-based administrative documentation render regular, timely farm visits physically impossible. By the time a farmer locates an extension agent or an agent inspects an afflicted plot, the biological window for effective disease mitigation has almost always lapsed.")
    add_para(doc, "In recent years, the telecommunications landscape in Ethiopia has undergone an unprecedented digital transformation. Driven by aggressive cellular network expansion by Ethio Telecom and Safaricom Ethiopia, 4G cellular data coverage has penetrated deep into rural Woredas and agrarian corridors. Concurrently, the availability of low-cost, budget Android smartphones equipped with high-resolution digital cameras has risen dramatically among rural and peri-urban agrarian households. This technological proliferation establishes a fertile and historic foundation for digital agricultural transformation.")
    add_para(doc, "Project Massaye (meaning 'My Farmland' in Amharic) is conceived and engineered as an end-to-end intelligent agricultural advisory and management ecosystem. By synthesizing state-of-the-art computer vision deep learning with localized, multi-tier web and mobile tele-consultation workflows, Massaye democratizes expert phytopathological diagnostics for smallholder farmers while arming agricultural extension agents and government administrators with unprecedented administrative and epidemiological control.")

    add_h2(doc, "1.2 Statement of the Problem")
    add_para(doc, "Despite decades of substantial public investments in agricultural extension infrastructure and rural human capital development, crop disease management among Ethiopian smallholders remains reactive, inefficient, and systematically dysfunctional. Critical structural bottlenecks in the existing system include:")
    add_bullet(doc, "Prohibitive Diagnostic Latency and Accelerated Crop Loss: Biological crop disease pathogens exhibit exponential infection cycles, often completing a full sporulation and spore dispersal phase within 48 to 72 hours under warm, humid field conditions. Under the prevailing conventional extension model, when a farmer detects foliar abnormalities, they must walk hours to the Kebele FTC. If the Crop Development Agent is conducting field visits elsewhere, attending administrative meetings at the Woreda town, or on leave, the farmer returns without guidance. The resulting latency between initial symptom detection and physical agent inspection averages between 5 and 12 days. In severe epidemics such as Late Blight or Rust, a 10-day delay translates directly into total crop destruction, forcing farming families into financial destitution and severe food insecurity.")
    add_bullet(doc, "Severe Diagnostic Inaccuracy and Indiscriminate Agrochemical Misuse: Smallholder farmers lack optical magnification or diagnostic reference materials. Symptoms of fungal leaf spots, bacterial wilts, and physiological micronutrient deficiencies are routinely confused. Unable to obtain prompt expert verification, farmers travel to local market towns and purchase broad-spectrum commercial chemicals based on arbitrary merchant advice. Studies indicate that over 50% of agrochemical applications by smallholder vegetable growers in Ethiopia are inappropriate for the targeted pathogen. This practice wastes scarce household financial capital, causes acute occupational chemical poisoning, contaminates rural groundwater sources, and accelerates pesticide resistance among local pathogen populations without saving the crop.")
    add_bullet(doc, "Overwhelming Extension Agent Workloads and Inequitable Geographic Coverage: In the vast majority of agricultural Woredas across Ethiopia, a single Kebele Crop Production Development Agent is tasked with serving between 800 and 1,500 dispersed rural households. A single agent cannot physically inspect more than 3 to 5 farms per day given the rugged mountainous terrain, dispersed settlement patterns, and absence of motorized transport. Consequently, farmers situated on the geographic peripheries of Kebeles are systematically disenfranchised from public advisory services.")
    add_bullet(doc, "Absence of Centralized Epidemiological Data and Outbreak Early Warning: Currently, when agricultural extension workers encounter crop diseases, details are recorded on physical paper ledgers or loose sheets stored in rural FTC offices. These paper records are vulnerable to physical deterioration, vermin, moisture damage, and loss. Monthly summary reports compiled for Woreda offices arrive weeks after an outbreak has initiated. At Zonal, Regional, and National Ministry levels, decision-makers have zero real-time spatial visibility into disease distribution vectors, preventing proactive containment measures such as targeted chemical buffer distributions or quarantine boundaries.")
    add_bullet(doc, "Linguistic, Literacy, and Communication Barriers: High-level agricultural research outputs, pest alerts, and registered chemical safety datasheets produced by national research institutes (such as EIAR) are predominantly published in English or complex academic Amharic. Rural farmers—many of whom possess limited formal literacy—are unable to interpret technical text, resulting in widespread misinterpretation of chemical dosage rates, dilution ratios, and safety harvest intervals.")

    add_h2(doc, "1.3 Objective")
    add_h3(doc, "General Objective")
    add_para(doc, "The general objective of this final year project is to conceptualize, design, develop, test, and deploy Massaye, an end-to-end intelligent agricultural advisory and management system that integrates deep learning computer vision with localized web and mobile tele-consultation workflows to empower Ethiopian farmers and agricultural extension personnel in diagnosing, managing, and tracking crop diseases.")
    
    add_h3(doc, "Specific Objectives")
    add_para(doc, "To accomplish the overarching general objective, the project executes the following specific, measurable, achievable, relevant, and time-bound (SMART) objectives:")
    add_bullet(doc, "To engineer and train a high-performance deep convolutional neural network (CNN) image classification pipeline capable of classifying major foliar diseases of dominant Ethiopian crops (Maize, Wheat, Tomato, Potato, Pepper) from smartphone field photographs with a validated classification accuracy exceeding 90%.")
    add_bullet(doc, "To design and develop a user-centric, offline-responsive cross-platform mobile application (Flutter) exclusively for the Farmer role, incorporating intuitive visual iconography, Amharic and English bilingual localization, real-time animated typewriter diagnosis streaming, and direct camera integration.")
    add_bullet(doc, "To engineer a reactive web management portal using React/Vite and Tailwind CSS tailored for Kebele Field Extension Officers, Woreda Lead Officers, and System Administrators to facilitate consultation triage, clinical image analysis, and digital prescription issuance.")
    add_bullet(doc, "To build an automated, geographically normalized consultation routing engine within the Django REST backend that dynamically binds farmer consultation tickets to certified extension officers according to official Kebele administrative boundaries.")
    add_bullet(doc, "To implement a full-duplex, real-time messaging subsystem utilizing WebSockets (Django Channels) supporting bidirectional text messaging and compressed voice notes, enabling illiterate and semi-literate farmers to communicate directly with specialists.")
    add_bullet(doc, "To develop an administrative epidemiological outbreak heatmap and analytical reporting engine providing Woreda and Zonal agricultural directors with real-time spatial intelligence regarding disease distribution vectors.")
    add_bullet(doc, "To rigorously evaluate the system through comprehensive unit, integration, usability, and user acceptance testing (UAT) against defined functional, performance, security, and reliability metrics.")

    add_h2(doc, "1.4 Methodology")
    add_para(doc, "To develop a software system that is both technically robust and socio-technically grounded in the authentic operational realities of Ethiopian agriculture, a systematic Object-Oriented Analysis and Design (OOAD) methodology was combined with an Agile Scrum development framework.")
    
    add_h3(doc, "Requirement Gathering Methods")
    add_para(doc, "Requirements elicitation utilized a multi-methodological triangulation strategy:")
    add_bullet(doc, "Semi-Structured Interviews: Conducted with 12 smallholder cereal and vegetable farmers, 6 Kebele Crop Development Agents, and 2 Woreda Agricultural Supervisors in North Shewa and surrounding agrarian corridors. These interviews elicited practical data regarding typical disease detection timelines, pesticide purchasing habits, smartphone literacy levels, and extension reporting bottlenecks.")
    add_bullet(doc, "Field Observations: The development team observed routine diagnostic interactions and farmer consultations at rural Kebele FTCs. This observation documented the physical distances traveled by farmers, the inspection procedures utilized by extension agents, and the physical ledgers maintained for case logging.")
    add_bullet(doc, "Document and Secondary Data Analysis: Analyzed official Ethiopian Ministry of Agriculture extension training manuals, Crop Protection Guidelines, national pesticide registration gazettes, and Central Statistical Agency agrarian sample surveys. This analysis established official administrative geographic hierarchies (Region -> Zone -> Woreda -> Kebele) and formal disease diagnostic criteria.")
    add_bullet(doc, "Domain Literature Review: Conducted exhaustive surveys of contemporary scientific publications regarding convolutional neural networks, transfer learning, residual networks (ResNet), lightweight mobile architectures (MobileNetV2), and mobile agricultural informatics in developing economies.")

    add_h3(doc, "Requirement Modelling Approach")
    add_para(doc, "The project adopts an Object-Oriented Analysis and Design (OOAD) modeling paradigm utilizing the Unified Modeling Language (UML 2.5). OOAD was selected due to the presence of distinct, highly interactive, and persistent entities (Users, Kebeles, Disease Predictions, Consultations, Prescriptions, Messages, and Agricultural Guides) exhibiting encapsulated data attributes, complex state transitions, and role-based operational policies. Dynamic system behaviors are specified using Use Case Diagrams, Sequence Diagrams, Activity Diagrams, and State Chart Diagrams, while static structural architectures are modeled using CRC (Class-Responsibility-Collaborator) cards, Analysis Class Diagrams, and Relational Entity-Relationship Diagrams (ERD).")

    add_h3(doc, "Tools and Technologies Used")
    add_para(doc, "The software engineering toolchain incorporates modern, robust, and open-source frameworks across each subsystem tier:")
    tools_headers = ["Layer / Subsystem", "Technology / Framework", "Version / Spec", "Engineering Justification"]
    tools_data = [
        ["Mobile Client", "Flutter / Dart", "Flutter 3.24.x / Dart 3.5.x", "Single-codebase cross-platform compilation (Android APK), 60 FPS reactive UI, direct hardware camera/microphone API access."],
        ["Web Frontend", "React.js / Vite", "React 18.x / Vite 5.x", "High-performance Single Page Application (SPA), component reusability, fast build cycles, reactive DOM management."],
        ["Styling & Icons", "Tailwind CSS / Lucide", "Tailwind 3.4.x", "Utility-first responsive design, consistent design tokens, agricultural color palettes, rapid UI assembly."],
        ["Backend REST API", "Python / Django / DRF", "Python 3.11 / Django 5.1 / DRF 3.15", "Enterprise-grade security, rapid ORM mapping, native authentication, built-in migration management, scalable REST endpoints."],
        ["Real-time Server", "Django Channels / Daphne", "Channels 4.x / Daphne ASGI", "Full-duplex bidirectional WebSocket server for instant chat, typing indicators, and real-time alert broadcasts."],
        ["Relational DBMS", "PostgreSQL / SQLite", "PostgreSQL 16 (Prod) / SQLite 3 (Dev)", "ACID compliance, spatial relational indexing, robust foreign key constraints, high concurrency under transactional workloads."],
        ["AI / Deep Learning", "PyTorch / Torchvision", "PyTorch 2.4.x", "Training, transfer learning, fine-tuning, and inference execution of deep convolutional neural network plant disease models."],
        ["Mobile State Mgmt", "BLoC Pattern", "flutter_bloc 8.1.6", "Predictable, testable unidirectional data flow, clean decoupling of business logic from UI rendering trees."],
        ["HTTP Networking", "Dio (Mobile) / Axios (Web)", "Dio 5.11 / Axios 1.7", "Robust HTTP transport with automatic JWT bearer token refresh interceptors, timeouts, and multipart upload handling."],
        ["Version Control", "Git / GitHub", "Git 2.45+", "Distributed team source code management, feature branching, code review pull requests, and automated deployment scripts."]
    ]
    add_styled_table(doc, tools_headers, tools_data, "Table 1.1: Comprehensive Engineering Technology Stack")

    add_h2(doc, "1.5 Feasibility Study")
    add_para(doc, "To verify the viability, sustainability, and practical applicability of Massaye within the target operating environment, an exhaustive five-dimensional feasibility study was executed.")
    
    add_h3(doc, "1.5.1 Economic Feasibility")
    add_para(doc, "Economic feasibility evaluates whether the system's development, deployment, and operational expenses are justified by measurable financial and socio-economic returns:")
    add_bullet(doc, "Development Costs: The development of Massaye relies exclusively on open-source frameworks, software development kits (SDKs), and libraries (Python, Django REST Framework, Flutter, React, PostgreSQL, PyTorch), eliminating proprietary licensing fees entirely. Development workstations and testing devices utilized existing university computing laboratory infrastructure.")
    add_bullet(doc, "Operational & Hosting Costs: Production backend hosting on virtual private cloud servers (VPS) or Ethiopian national data infrastructure (e.g., Ethio Telecom Cloud) requires modest computational capacity (approx. 4 vCPUs, 8 GB RAM, 100 GB SSD), incurring negligible annual operating overhead.")
    add_bullet(doc, "Socio-Economic Return to Farmers: The economic loss incurred by a single smallholder hectare of maize or wheat afflicted with late-stage rust or blight ranges between 35,000 and 120,000 Ethiopian Birr (ETB). By detecting foliar infections 7 to 14 days earlier than manual methods, Massaye preserves between 40% and 80% of threatened yields. A smallholder household investing less than 10 ETB in mobile data per scan protects tens of thousands of Birr in net crop equity per season. The benefit-to-cost ratio is overwhelmingly positive, confirming robust economic feasibility.")

    add_h3(doc, "1.5.2 Technical Feasibility")
    add_para(doc, "Technical feasibility assesses whether the development team possessed adequate engineering competency, software toolchains, and hardware environments to successfully realize the system:")
    add_bullet(doc, "Engineering Competency: The project team acquired mastery over object-oriented software engineering, relational database normalization, Python web frameworks, mobile app architecture, and machine learning pipelines through the accredited DBU Information Systems curriculum.")
    add_bullet(doc, "Hardware Infrastructure Compatibility: Budget Android smartphones widely owned by Ethiopian rural households feature camera sensors exceeding 8 Megapixels and at least 2 GB of RAM. The Flutter mobile application was engineered with lightweight rendering trees, consuming less than 90 MB of runtime RAM, ensuring smooth execution even on entry-level Android devices.")
    add_bullet(doc, "Network Resilience: The backend architecture utilizes aggressive payload compression (transferring images under 400 KB and structured JSON payloads under 2 KB), resilient connection timeouts, and automatic retry policies, guaranteeing reliable communication over fluctuating rural 3G and 4G networks.")

    add_h3(doc, "1.5.3 Operational Feasibility")
    add_para(doc, "Operational feasibility examines the ease with which end-users (rural farmers, extension agents, and agricultural directors) will integrate the software into their daily routines:")
    add_bullet(doc, "User Experience for Semi-Literate Farmers: The mobile app features large high-contrast touch controls (minimum 48x48 dp), clear agricultural iconography, full Amharic and English translation, and audio voice note messaging, removing literacy barriers.")
    add_bullet(doc, "Extension Workflow Alignment: The web portal reinforces the established administrative chain of command: consultations are automatically partitioned and routed strictly by Kebele and Woreda jurisdictions, preserving the authority and existing operational protocols of Woreda Lead Officers and Kebele DAs.")

    add_h3(doc, "1.5.4 Political and Legal Feasibility")
    add_bullet(doc, "National Policy Alignment: Massaye aligns directly with the Digital Ethiopia 2025 Strategy, which explicitly identifies digital agriculture, mobile extension delivery, and agrarian data modernization as key national economic transformation imperatives.")
    add_bullet(doc, "Data Protection and Agronomic Compliance: User credentials, location coordinates, and farm photos are secured with salted bcrypt hashing and tokenized JWT authentication. Agrochemical prescriptions generated within the system comply with registered Ethiopian Ministry of Agriculture pesticide safety directives, mitigating off-label chemical hazards.")

    add_h3(doc, "1.5.5 Time / Schedule Feasibility")
    add_para(doc, "The project was structured across a 28-week academic calendar using the Agile Scrum development framework. Milestones were completed within the defined schedule:")
    schedule_headers = ["Phase", "Milestone / Work Package", "Duration", "Start Week", "Finish Week", "Key Deliverables"]
    schedule_data = [
        ["Phase 1", "Problem Identification & Domain Study", "4 Weeks", "Week 1", "Week 4", "Proposal & Requirement Specification Document"],
        ["Phase 2", "System Modeling & OOAD (UML)", "4 Weeks", "Week 5", "Week 8", "UML Diagrams, CRC Cards, Class Models, ERD"],
        ["Phase 3", "AI CNN Model Training & Inference Pipeline", "5 Weeks", "Week 9", "Week 13", "Trained PyTorch Model, Model Evaluation Report"],
        ["Phase 4", "Backend REST API & Database Construction", "5 Weeks", "Week 14", "Week 18", "Django REST API, PostgreSQL Schema, Token Auth"],
        ["Phase 5", "Frontend Web & Mobile App Construction", "5 Weeks", "Week 19", "Week 23", "Flutter Android APK, React Web Management Portal"],
        ["Phase 6", "Subsystem Integration, Testing & Validation", "3 Weeks", "Week 24", "Week 26", "Test Case Execution Matrix, Bug Resolution Logs"],
        ["Phase 7", "Final Documentation & Oral Defense Prep", "2 Weeks", "Week 27", "Week 28", "Comprehensive Final Project Report & Slide Deck"]
    ]
    add_styled_table(doc, schedule_headers, schedule_data, "Table 1.2: Project Development Work Plan and Schedule Matrix")

    add_h2(doc, "1.6 Project Scope and Limitation")
    add_h3(doc, "1.6.1 Project Scope")
    add_para(doc, "The functional, architectural, and operational scope of Massaye encompasses:")
    add_bullet(doc, "Geographic Hierarchy Administration: Multi-level administrative CRUD management spanning Regions, Zones, Woredas, and Kebeles across Ethiopia.")
    add_bullet(doc, "Deep Learning Foliar Diagnostics: Real-time image-based detection of dominant foliar diseases across five major Ethiopian staple and horticultural crops: Maize (Leaf Blight, Common Rust), Wheat (Stem Rust), Tomato (Early Blight, Late Blight), Potato (Early Blight, Late Blight), and Pepper (Bacterial Spot).")
    add_bullet(doc, "End-to-End Tele-Consultation Management: Structured case ticketing enabling farmers to escalate AI predictions into formal consultation requests, supporting status lifecycles from NEW to ASSIGNED, WAITING_FOR_FARMER, RESOLVED, and CLOSED.")
    add_bullet(doc, "Multimodal Real-Time Communication: Bidirectional text messaging and compressed voice note transmission between farmers and assigned extension officers over persistent WebSocket connections.")
    add_bullet(doc, "Agricultural Knowledge Base: Digital publishing, management, and offline mobile caching of vetted agronomic pest control guides, organic treatments, and seasonal planting advice in Amharic and English.")
    add_bullet(doc, "Epidemiological Outbreak Analytics: Geographic Information System (GIS) mapping and statistical dashboards plotting disease incidence frequencies across Woredas and Kebeles.")

    add_h3(doc, "1.6.2 Project Limitations")
    add_bullet(doc, "Symptom Boundary: The computer vision model classifies foliar pathologies exhibiting visible optical symptoms on leaf surfaces; it does not identify subterranean root-knot nematodes, vascular wilts prior to foliar display, or soil salinity.")
    add_bullet(doc, "Hardware Prerequisite: Diagnostic image capture requires a mobile smartphone equipped with an operational digital camera sensor; feature phones without cameras cannot utilize the computer vision diagnostic module.")
    add_bullet(doc, "Connectivity Prerequisite for Inference: While educational guides and historical records are cached locally on the mobile device, initial AI diagnosis requires active cellular data connectivity to transmit image tensors to the backend cloud inference server.")

    add_h2(doc, "1.7 Significance of the Project")
    add_para(doc, "The successful deployment of Massaye delivers multi-dimensional benefits across Ethiopian society:")
    add_bullet(doc, "For Smallholder Farming Households: Provides immediate 24/7 access to expert-grade crop diagnosis, halts disease progression before total harvest destruction, eliminates unnecessary travel to distant towns, prevents financial loss from improper agrochemical purchases, and elevates household economic stability.")
    add_bullet(doc, "For Frontline Extension Agents (DAs): Eliminates exhausting, redundant physical foot travel to distant plots for routine visual inspections, organizes inquiries into structured digital queues, and provides historical case records to support accurate clinical prescriptions.")
    add_bullet(doc, "For Woreda and Zonal Agricultural Offices: Replaces fragmented, slow paper reporting with real-time epidemiological intelligence, enabling rapid mobilization of emergency agrochemical supplies and containment of pathogen vectors.")
    add_bullet(doc, "For the Information Systems Academic Community: Establishes a reference architecture demonstrating how modern computer vision and distributed web/mobile systems can be pragmatically designed to solve real-world developmental challenges in agrarian economies.")

    add_h2(doc, "1.8 Organization of the Project")
    add_para(doc, "This project documentation is structured into six comprehensive chapters in strict conformance with the Debre Berhan University Department of Information Systems Guidelines:")
    add_bullet(doc, "Chapter One (Introduction): Presents the project background, statement of the problem, general and SMART specific objectives, methodologies, five-dimensional feasibility studies, scope, and significance.")
    add_bullet(doc, "Chapter Two (Requirement Specification and Object-Oriented Analysis): Analyzes the legacy manual extension system, specifies functional/non-functional requirements and business rules, details comprehensive UML analysis models (Use Case, Sequence, State Chart, Activity), CRC abstraction cards, class diagrams, and change cases.")
    add_bullet(doc, "Chapter Three (Object-Oriented System Design): Details the design goals, three-tier software architecture, subsystem decompositions, UML component and deployment diagrams, relational ERD schemas, data dictionaries, and access control matrices.")
    add_bullet(doc, "Chapter Four (Implementation, Testing, and Maintenance): Introduces development languages, IDEs, and frameworks, defines coding standards, and presents unit, integration, and user acceptance test plans alongside an empirical test execution matrix.")
    add_bullet(doc, "Chapter Five (Results and Discussion): Provides a walkthrough of mobile and web interface modules, system screen snapshots, and relational database realizations.")
    add_bullet(doc, "Chapter Six (Conclusions and Recommendations): Synthesizes project achievements against objectives, discusses practical implications, acknowledges limitations, and articulates actionable recommendations for policymakers, practitioners, and future researchers.")
    
    doc.add_page_break()
    print("Chapter 1 successfully built!")
    return doc
